style.css:
@-moz-document domain("pippit.ai") {
/* 1. LÓGICA DE INVERSÃO (FUNDO CINZA OPACO) */

    html[translate="no"] {

        filter: invert(0.9) hue-rotate(180deg) !important;

        background-color: #fff !important; 

    }


    /* 2. PROTEÇÃO EXCLUSIVA DE MÍDIA (Cores Reais) */

    /* Aqui dizemos para o navegador inverter de volta apenas o que for imagem ou vídeo */

    img, 

    video, 

    canvas, 

    .lv-avatar-image, 

    .main-image,

    .preview-zZdXDg img,

    .preview-zZdXDg video,

    [style*="background-image"] {

        filter: invert(1) hue-rotate(-180deg) !important;

    }

    /* 3. ARREDONDAMENTO DA MINIATURA (LAPIDAÇÃO) */
  
    /* Aqui suavizamos o fundo branco/claro que você mencionou */
  
    .preview-zZdXDg {
      
        border-radius: 12px !important; /* Arredonda os cantos */
      
        overflow: hidden !important;    /* Garante que o conteúdo siga a curva */
      
        background-color: transparent !important; /* Tenta suavizar o brilho */
      
    }


    /* 4. CONTRASTE NAS PALAVRAS (TEXTO CLARO) */

    h1, h2, h3, h4, 

    .container-heoiWJ, 

    .lv-typography,

    .title-TH1h3B,

    .title-OJ8wJP,

    .title-GDJTKO,

    .tabText-sEUGq3,

    .inner-menu-vxqa5d,

    .lv-menu-item,

    span, p, a, strong, b {

        color: #000000 !important; /* Aparece branco na tela */

        text-shadow: none !important;

        -webkit-font-smoothing: antialiased !important;

    }


    /* 5. AJUSTE DA BARRA LATERAL E CAIXA DE TEXTO */

    .side-menu-ZO7IeA, 

    .nav-wrapper-IYMMcM,

    .sc-bbSZdi.gNUxix,

    .featureCard-wvtgZm,

    .preview-zZdXDg,

    .ag-ui-conversation-input-container,
  
    .featureCard-wvtgZm { /* Agora o card popular fica escuro como o resto */
      
        background-color: #ffffff !important; 
      
        border: 1px solid #eeeeee !important; 
      
        box-shadow: none !important;

    }


    /* 6. CORREÇÃO DAS MARGENS E BORDAS */

    .lv-divider, .lv-divider-vertical, .arco-divider {

        background-color: #ffffff !important;

        border-color: #ffffff !important;

    }


    /* 7. ÍCONES (PARA APARECEREM BRANCOS) */

    .icon-wrap-UdBCMO svg, 

    .logo-img-xcttiv svg g,

    .onboardingEntry-icon-mQj2Tb g {

        fill: #000000 !important; 

    }


    /* 8. LIMPANDO O TOPO E MÁSCARAS */

    .dotMask-QnC2AX, .blurMask-Bbe1Wp {

        display: none !important;

    }


    /* 9. VARIÁVEIS DE SISTEMA */

    body[lv-theme], body.lv-theme-force_light {

        --BGPrimary: #ffffff !important;

        --TextPrimary: #000000 !important;

        background: #ffffff !important;

    }
}
